def take_lock(ledger, by):
    path = ledger + ".lock"
    for attempt in (1, 2):
        try:
            fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            age = time.time() - os.path.getmtime(path)
            holder = open(path, encoding="utf-8").read().strip()
            if age < LOCK_TTL_S or attempt == 2:
                fail(f"ledger is locked by {holder} ({int(age)}s ago). Don't edit; retry on the next wake.")

            print(f"WARN: taking over abandoned lock ({holder}, {int(age)}s old)")
            os.remove(path)
            continue
        os.write(fd, f"{by} at {time.strftime('%Y-%m-%dT%H:%M:%S')}".encode())
        os.close(fd)
        return


def release_lock(ledger):
    try:
        os.remove(ledger + ".lock")
