        pass


def lint_graph(block):
    """Print the mission graph's staleness warnings. Read-only; never changes verify's result."""
    m = re.search(r"MISSION_GRAPH(?:\*\*|`)?[ \t]*:[ \t]*(?:\*\*|`)?[ \t]*([^\n`*]+)", block)
    if not m or not os.path.isfile(os.path.expanduser(m.group(1))):
        return
    try:
        sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
        import graph_lint
        p = re.search(r"(?m)^[ \t]*(?:[-*][ \t]*)?(?:\*\*|`)?PROJECT(?:\*\*|`)?[ \t]*:[ \t]*(?:\*\*|`)?[ \t]*(~?/[^\s`*]+)", block)
        warns = graph_lint.lint(m.group(1), project=os.path.expanduser(p.group(1)) if p else None)
    except Exception as e:
        print(f"WARN: graph lint skipped ({type(e).__name__}: {e})")

        return
    if warns:
        print(f"Graph lint for {m.group(1)} (warnings only; nothing blocked):")
        print("\n".join(warns))


