def stop(code: int, status: str, reason: str, **fields: Any) -> "NoReturn":
    emit(status, reason=reason, **fields)
    raise SystemExit(code)


def normalize(value: Any) -> Any:
    if isinstance(value, str):
        return unicodedata.normalize("NFC", value)
    if isinstance(value, list):
        return [normalize(item) for item in value]
    if isinstance(value, dict):
        return {unicodedata.normalize("NFC", str(key)): normalize(item) for key, item in value.items()}
    return value


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(normalize(value), ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def parse_json(raw: str, label: str) -> Any:
    try:
        return json.loads(raw)
    except json.JSONDecodeError as exc:
        stop(EXIT_DENIED, "denied", f"malformed_{label}", detail=str(exc))

def load_missions(state_path: Path) -> dict[str, list[dict[str, str]]]:
    try:
        text = state_path.read_text(encoding="utf-8")
    except OSError as exc:
        stop(EXIT_DENIED, "denied", "director_state_unreadable", detail=str(exc))

    blocks = re.split(r"(?m)(?=^## Mission: )", text)
    missions: dict[str, list[dict[str, str]]] = {}
    for block in blocks:
        fields = dict(re.findall(r"(?m)^([A-Z][A-Z0-9_]*):[ \t]*(.*?)[ \t]*$", block))  # [ \t]: an empty field stays empty instead of swallowing the next line
        mission_id = fields.get("MISSION_ID")
        if mission_id:
            missions.setdefault(mission_id, []).append(fields)
    return missions


def mission_fields(state_path: Path, mission_id: str) -> dict[str, str]:
    matches = load_missions(state_path).get(mission_id, [])
    if len(matches) != 1:
