        stop(EXIT_DENIED, "denied", "caller_selected_runtime_path")
    try:
        state = scope.ledger_path(home, home / "DIRECTOR_STATE.md")
        root_input = scope.claims_path(home)
        scope.private_file(root_input.parent / (root_input.name + ".steps.lock"))
    except (scope.ScopeError, OSError) as exc:

        stop(EXIT_DENIED, "denied", "invalid_team_path", detail=str(exc))

    if root_input.is_symlink():
        stop(EXIT_DENIED, "denied", "claim_root_symlink")
    try:
        if not root_input.exists() and not create_root:
            return state, root_input
        if create_root:
            root_input.mkdir(parents=True, exist_ok=True, mode=0o700)
        root = root_input.resolve(strict=True)
        if root.is_symlink() or root.stat().st_uid != os.getuid():
            stop(EXIT_DENIED, "denied", "claim_root_untrusted")
        if create_root:
            root.chmod(0o700)
    except OSError as exc:
        stop(EXIT_DENIED, "denied", "claim_root_unavailable", detail=str(exc))
    return state, root


def atomic_json(path: Path, payload: dict[str, Any]) -> None:
    fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    tmp = Path(tmp_name)
    try:
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(canonical_bytes(payload))
            handle.flush()
            os.fsync(handle.fileno())

        os.replace(tmp, path)
        dir_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
    finally:
        if tmp.exists():
            tmp.unlink()


def atomic_json_create(path: Path, payload: dict[str, Any]) -> bool:
    fd, tmp_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    tmp = Path(tmp_name)
    try:
        os.fchmod(fd, 0o600)
        with os.fdopen(fd, "wb") as handle:
            handle.write(canonical_bytes(payload))
            handle.flush()
            os.fsync(handle.fileno())
        try:
            os.link(tmp, path)
        except FileExistsError:
            return False
        dir_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(dir_fd)
        finally:
            os.close(dir_fd)
        return True
    finally:
        if tmp.exists():
            tmp.unlink()


