def authorization_steps(args: argparse.Namespace, scope: Any) -> list[dict[str, Any]] | None:
    """The scope's ordered steps, or None for a single-write scope (which keeps its exact old checks)."""
    if not isinstance(scope, dict):
        stop(EXIT_DENIED, "denied", "authorization_scope_not_object")
    if "steps" not in scope:
        if args.step is not None or args.step_write is not None:
            stop(EXIT_DENIED, "denied", "authorization_scope_has_no_steps")
        return None
    steps = scope["steps"]
    if not isinstance(steps, list) or not steps:
        stop(EXIT_DENIED, "denied", "authorization_scope_steps_invalid")
    if any(key in scope for key in STEP_FIELDS):
        stop(EXIT_DENIED, "denied", "authorization_scope_mixed_format")
    for number, step in enumerate(steps, 1):
        if not isinstance(step, dict):

            stop(EXIT_DENIED, "denied", "authorization_scope_step_invalid", step=number, field="step")
        for key in STEP_FIELDS:
            value = step.get(key)
            if not isinstance(value, str) or not value.strip():
                stop(EXIT_DENIED, "denied", "authorization_scope_step_invalid", step=number, field=key)
        limit = step.get("max")
        if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
            stop(EXIT_DENIED, "denied", "authorization_scope_step_invalid", step=number, field="max")
    return steps


def write_identity(provider: str, action: str, account: str, resource_type: str, resource: str) -> dict[str, str]:
    return {
        "provider": normalize(provider).casefold(),
