        "account": normalize(account),
        "resource_type": normalize(resource_type).casefold(),
        "resource": normalize(resource),
    }


def locate_step(args: argparse.Namespace, steps: list[dict[str, Any]]) -> int:

"""The 1-based step these exact CLI arguments name (--step picks one when two steps are identical)."""
if args.step_write is not None and args.step_write < 1:
    stop(EXIT_DENIED, "denied", "step_write_invalid")
wanted = write_identity(args.provider, args.action, args.account, args.resource_type, args.resource_target)
if args.step is not None:
    if not 1 <= args.step <= len(steps):
        stop(EXIT_DENIED, "denied", "step_out_of_range", step=args.step, steps=len(steps))
    have = write_identity(*(steps[args.step - 1][key] for key in STEP_FIELDS))
    for key in STEP_FIELDS:
        if have[key] != wanted[key]:
            stop(EXIT_DENIED, "denied", f"authorization_scope_{key}_mismatch", step=args.step)
    return args.step
matches = [number for number, step in enumerate(steps, 1) if write_identity(*(step[key] for key in STEP_FIELDS)) == wanted]
if not matches:
    stop(EXIT_DENIED, "denied", "authorization_scope_step_mismatch")
if len(matches) > 1:

        stop(EXIT_DENIED, "denied", "step_ambiguous", matching_steps=matches)
    return matches[0]


def resource_key_for(provider: str, account: str, resource_type: str, target: str) -> str:
    return digest({
