def step_intent_id(args: argparse.Namespace, steps: list[dict[str, Any]], number: int, write: int, outcome_hash: str, scope_hash: str) -> str:
    """One deterministic intent per (fence, step, write); the node is recorded in the claim, not keyed."""
    step = steps[number - 1]
    return digest({
        "schema": "controller-write-intent/v2",
        "mission_id": args.mission_id,
        "next_play_id": args.next_play_id,
        "step": number,
