def node_validation_error(fields: dict[str, str], node_id: str) -> str | None:
    graph_value = fields.get("MISSION_GRAPH", "")
    if not graph_value:
        return "mission_graph_missing"
    try:
        resolved = scope.graph_path(canonical_home(), graph_value)
        graph_text = resolved.read_text(encoding="utf-8")
        _, binding = scope.bound_home(__file__)
        scope.check_text_identity(binding, graph_text)
    except (OSError, scope.ScopeError):
        return "mission_graph_untrusted"
    matches = re.findall(rf"(?m)^## Node:\s*{re.escape(node_id)}\s*$", graph_text)
    if len(matches) != 1:
        return "mission_node_ambiguous"
    return None


def validate_node(fields: dict[str, str], node_id: str) -> None:
    if reason := node_validation_error(fields, node_id):
        stop(EXIT_DENIED, "denied", reason)


