def claim_paths(root: Path, resource_key: str) -> tuple[Path, Path, Path]:
    if not SAFE_KEY.fullmatch(resource_key):
        stop(EXIT_DENIED, "denied", "malformed_resource_key")
    claim_dir = root / resource_key
    if claim_dir.is_symlink():
        stop(EXIT_DENIED, "denied", "claim_entry_symlink")
    if claim_dir.exists() and (not claim_dir.is_dir() or claim_dir.stat().st_uid != os.getuid()):
        stop(EXIT_DENIED, "denied", "claim_entry_untrusted")
    return claim_dir, claim_dir / "claim.json", claim_dir / "receipt.json"


