def install_new_attempt(claim_dir: Path, claim: dict[str, Any]) -> None:
    transition = claim_dir / ".transition"
    try:
        transition.mkdir(mode=0o700)
    except FileExistsError:
        stop(EXIT_ACTIVE, "reconcile_active", "resource_transition_unresolved", resource_key=claim["resource_key"])
    try:
        current_path = claim_dir / "claim.json"
        terminal_path = claim_dir / "receipt.json"
        current = read_json(current_path)
        terminal = read_json(terminal_path)
        old_intent = str(current.get("write_intent_id", ""))
        resource_key = str(current.get("resource_key", ""))
        if old_intent == claim["write_intent_id"]:
            if failure_is_valid(terminal, resource_key, old_intent):
                stop(EXIT_DENIED, "replay_failed", "prior_attempt_failed", resource_key=claim["resource_key"], write_intent_id=old_intent)
            if receipt_is_valid(terminal, resource_key, old_intent):
                stop(EXIT_DENIED, "denied", "stale_historical_intent", resource_key=claim["resource_key"], write_intent_id=old_intent)

        if failure_is_valid(terminal, resource_key, old_intent):
            archived_name = "failure.json"
        elif receipt_is_valid(terminal, resource_key, old_intent):
            archived_name = "receipt.json"
        else:
            stop(EXIT_POISONED, "poisoned", "failure_receipt_invalid")

        history_root = claim_dir / "history"
        if history_root.is_symlink():
            stop(EXIT_POISONED, "poisoned", "claim_history_untrusted")
        history_root.mkdir(mode=0o700, exist_ok=True)
        history_root.chmod(0o700)
        history = history_root / old_intent
        history.mkdir(parents=True, mode=0o700)
        history.chmod(0o700)
        os.replace(current_path, history / "claim.json")
        os.replace(terminal_path, history / archived_name)
        atomic_json(current_path, claim)
    finally:
        try:
            transition.rmdir()
        except OSError:
            pass


def write_state(root: Path, resource_key: str, write_intent_id: str) -> tuple[str, dict[str, Any]]:

"""Where one write intent stands on its resource: absent, active, completed, failed or unresolved."""
claim_dir, claim_path, receipt_path = claim_paths(root, resource_key)
if not claim_dir.exists():
    return "absent", {}
transition = claim_dir / ".transition"
if transition.exists() or transition.is_symlink():
    return "unresolved", {}
history_root = claim_dir / "history"
history = history_root / write_intent_id
if history_root.is_symlink() or history.is_symlink():
    stop(EXIT_POISONED, "poisoned", "claim_history_untrusted")
if history.is_dir():
    for name, is_valid, state in (("receipt.json", receipt_is_valid, "completed"), ("failure.json", failure_is_valid, "failed")):
        path = history / name
        if path.exists() or path.is_symlink():
            record = read_json(path)
            if is_valid(record, resource_key, write_intent_id):
                return state, record
    stop(EXIT_POISONED, "poisoned", "claim_history_invalid", resource_key=resource_key)
claim = read_json(claim_path)

    if claim.get("write_intent_id") != write_intent_id:
        return "absent", {}
    if receipt_path.exists() or receipt_path.is_symlink():
        record = read_json(receipt_path)
        if receipt_is_valid(record, resource_key, write_intent_id):
            return "completed", record
        if failure_is_valid(record, resource_key, write_intent_id):
            return "failed", record
        stop(EXIT_POISONED, "poisoned", "terminal_receipt_invalid", resource_key=resource_key)
    return "active", claim


