    except OSError as exc:
        stop(EXIT_DENIED, "denied", "step_lock_unavailable", detail=str(exc))
    if os.fstat(fd).st_uid != os.getuid():
        os.close(fd)
        stop(EXIT_DENIED, "denied", "step_lock_untrusted")
    wait = 10.0
    deadline = time.monotonic() + wait
    while True:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
