            time.sleep(0.05)


def acquire_step(args: argparse.Namespace, root: Path, steps: list[dict[str, Any]], number: int, outcome_hash: str, scope_hash: str) -> None:
    """Grant write `--step-write` of step `number` only after every earlier step completed under this fence."""
    lock = step_lock(root)
    try:
        grant_step(args, root, steps, number, outcome_hash, scope_hash)
    finally:
        os.close(lock)

def grant_step(args: argparse.Namespace, root: Path, steps: list[dict[str, Any]], number: int, outcome_hash: str, scope_hash: str) -> None:
    step = steps[number - 1]
    write = 1 if args.step_write is None else args.step_write
    where = {"step": number, "steps": len(steps), "step_write": write, "step_max": step["max"]}
    if write > step["max"]:
        stop(EXIT_DENIED, "denied", "step_max_reached", **where)
    resource_key = step_resource_key(step)
    write_intent_id = step_intent_id(args, steps, number, write, outcome_hash, scope_hash)

    # This exact write: a completed one replays its evidence; a failed or unresolved one never re-runs.
    state, record = write_state(root, resource_key, write_intent_id)
    if state == "completed":
        emit("replay_completed", resource_key=resource_key, write_intent_id=write_intent_id, target_id=record.get("target_id"), readback=record.get("readback"), **where)
        return
    if state == "failed":

    stop(EXIT_DENIED, "replay_failed", "prior_attempt_failed", resource_key=resource_key, write_intent_id=write_intent_id, sequence_stopped=True, **where)
if state == "active":
    stop(EXIT_ACTIVE, "reconcile_active", "intent_unresolved", resource_key=resource_key, write_intent_id=write_intent_id, **where)
if state == "unresolved":
    stop(EXIT_ACTIVE, "reconcile_active", "resource_transition_unresolved", resource_key=resource_key, **where)

# Every earlier step, and this step's earlier writes, completed in order under this fence.
for earlier in range(1, number + 1):
    earlier_key = step_resource_key(steps[earlier - 1])
    last = steps[earlier - 1]["max"] if earlier < number else write - 1
    completed = 0
    for ordinal in range(1, last + 1):
        earlier_intent = step_intent_id(args, steps, earlier, ordinal, outcome_hash, scope_hash)
        earlier_state, _ = write_state(root, earlier_key, earlier_intent)
        if earlier_state == "completed":
            completed += 1
            continue

        if earlier_state == "failed":
            stop(EXIT_DENIED, "denied", "prior_step_failed", failed_step=earlier, failed_write=ordinal, resource_key=earlier_key, write_intent_id=earlier_intent, sequence_stopped=True, **where)
        if earlier_state in ("active", "unresolved"):
            stop(EXIT_ACTIVE, "reconcile_active", "prior_step_unresolved", unresolved_step=earlier, unresolved_write=ordinal, resource_key=earlier_key, write_intent_id=earlier_intent, **where)
        break  # absent: writes are granted in order, so no later one exists
    if earlier < number and completed == 0:
        stop(EXIT_DENIED, "denied", "step_out_of_order", waiting_on_step=earlier, **where)
    if earlier == number and completed < write - 1:
        stop(EXIT_DENIED, "denied", "step_write_out_of_order", waiting_on_write=completed + 1, **where)

# A later step that has started closes this one.
for later in range(number + 1, len(steps) + 1):

    receipt = read_json(receipt_path)
    if receipt_is_valid(receipt, args.resource_key, args.write_intent_id):
        emit("replay_completed", resource_key=args.resource_key, write_intent_id=args.write_intent_id, target_id=receipt.get("target_id"), readback=receipt.get("readback"), **step_fields(receipt))
        return
    if failure_is_valid(receipt, args.resource_key, args.write_intent_id):
        stop(EXIT_DENIED, "replay_failed", "prior_attempt_failed", resource_key=args.resource_key, write_intent_id=args.write_intent_id, **step_fields(receipt))
    stop(EXIT_POISONED, "poisoned", "terminal_receipt_invalid")
claim = read_json(claim_path)
if claim.get("write_intent_id") != args.write_intent_id or claim.get("status") != "active":
    stop(EXIT_DENIED, "denied", "claim_intent_mismatch")
validate_claim_fence(state, claim)
if not args.target_id.strip():
    stop(EXIT_DENIED, "denied", "target_id_missing")
readback = parse_json(args.readback_json, "readback_json")
if not isinstance(readback, dict) or not readback:

        emit("replay_completed", resource_key=args.resource_key, write_intent_id=args.write_intent_id, target_id=existing.get("target_id"), readback=existing.get("readback"), **step_fields(existing))
        return
    stop(EXIT_DENIED, "denied", "completed_resource_conflict", resource_key=args.resource_key)


