SEP = " | "


class Refused(Exception):
    pass


def now_stamp():
    return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%MZ")


def parse_row(line):
    return [c.strip() for c in line.strip()[1:-1].split(SEP)]


def fmt_row(cells):
    return "| " + SEP.join(cells) + " |"


def check_cell(col, value):
    if not isinstance(value, str):
        raise Refused(f"{col}: the value must be text")
    if SEP in value:
        raise Refused(f'{col}: a cell can\'t contain " | " (it splits the table row); use "/" or ";" instead')
    if "\n" in value or "\r" in value:

        raise Refused(f"{col}: a cell can't contain a line break")
    return value.strip()


def header_value(lines, key):
    """A KEY: value line from the graph header (above the table and the first "## " section)."""
    for line in lines:
        if line.startswith("|") or line.startswith("## "):
            break
        m = re.match(rf"^{key}:\s*(.*)$", line)
        if m:
            return m.group(1).strip()
    return ""


def project_dir(lines):
    m = re.match(r"^[`*]*(~?/[^\s`*()]+)", header_value(lines, "PROJECT"))
    return os.path.expanduser(m.group(1)) if m else None


class Table:
    def __init__(self, text):
        self.lines = text.split("\n")
        self.hdr = next((i for i, l in enumerate(self.lines) if re.match(r"^\|\s*NODE_ID\s*\|", l)), None)
        if self.hdr is None:
            raise Refused("no node table (a '| NODE_ID | ...' header) in this graph")
        if self.hdr + 1 >= len(self.lines) or not re.match(r"^\|[\s:|-]+$", self.lines[self.hdr + 1]):
            raise Refused("no |---| separator row under the table header")

    self.cols = [c.strip() for c in self.lines[self.hdr].strip().strip("|").split("|")]
    self.end = self.hdr + 2
    while self.end < len(self.lines) and self.lines[self.end].startswith("|"):
        self.end += 1

def rows(self):
    return range(self.hdr + 2, self.end)

def find(self, node):
    hits = [i for i in self.rows() if parse_row(self.lines[i])[0] == node]
    if not hits:
        raise Refused(f"node not found: {node}")
    if len(hits) > 1:
        raise Refused(f"node {node} has {len(hits)} rows")
    return hits[0]

def cells(self, i):
    c = parse_row(self.lines[i])
    if len(c) != len(self.cols):
        raise Refused(f"row {i + 1} ({c[0]}) has {len(c)} cells for {len(self.cols)} columns; fix that row first")
    return c

def col(self, name):
    if name not in self.cols:
        raise Refused(f"no column {name} (columns: {', '.join(self.cols)})")
    return self.cols.index(name)

def put(self, i, cells):
    line = fmt_row(cells)

    if parse_row(line) != cells:
        raise Refused(f"row {cells[0]} wouldn't read back as written (a cell starts or ends with '|')")
    self.lines[i] = line

def stamp_node(self, cells, stamp):
    if "UPDATED_AT" in self.cols:
        cells[self.cols.index("UPDATED_AT")] = stamp

def stamp_file(self, stamp):
    for i in range(self.end, len(self.lines)):
        if self.lines[i].startswith("## "):
            return
        if self.lines[i].startswith("UPDATED_AT:"):
            self.lines[i] = "UPDATED_AT: " + stamp
            return

def add_column(self, col, after):
    if col in self.cols:
        return False
    k = self.col(after) + 1
    rows = [(i, self.cells(i)) for i in self.rows()]
    self.cols.insert(k, col)
    self.lines[self.hdr] = fmt_row(self.cols)
    self.lines[self.hdr + 1] = "|" + "---|" * len(self.cols)
    for i, c in rows:
        c.insert(k, "")
        self.put(i, c)
    return True

def text(self):
    return "\n".join(self.lines)

