def blocks(text):
    clean = re.sub(r"<!--.*?-->", _blank, text, flags=re.S)
    clean = re.sub(r"^(`{3,}|~{3,})[^\n]*\n.*?^\1[ \t]*$", _blank, clean, flags=re.S | re.M)
    lines, raw = clean.split("\n"), text.split("\n")
    out, i = [], 0
    while i < len(lines):
        m = MISSION.match(lines[i])
        if not m:
            i += 1
            continue
        j = i + 1
        while j < len(lines) and not HEADING.match(lines[j]):
            j += 1
        out.append((m.group(1), "\n".join(raw[i:j]).rstrip()))
        i = j
    return out


