def load_missions(state_path: Path) -> dict[str, list[dict[str, str]]]:
    try:
        text = io.read_text(state_path)
    except OSError as exc:
        stop(EXIT_DENIED, "denied", "director_state_unreadable", detail=str(exc))

    blocks = re.split(r"(?m)(?=^## Mission: )", text)
    missions: dict[str, list[dict[str, str]]] = {}
    for block in blocks:
        fields = scope.text_fields(block)  # [ \t]: an empty field stays empty instead of swallowing the next line
        mission_id = fields.get("MISSION_ID")
        if mission_id:
            missions.setdefault(mission_id, []).append(fields)
    return missions


