def authorization_steps(args: argparse.Namespace, scope: Any) -> list[dict[str, Any]] | None:
    """The scope's ordered steps, or None for a single-write scope (which keeps its exact old checks)."""
    if not isinstance(scope, dict):
        stop(EXIT_DENIED, "denied", "authorization_scope_not_object")
    if "steps" not in scope:
        if args.step is not None or args.step_write is not None:
            stop(EXIT_DENIED, "denied", "authorization_scope_has_no_steps")
        return None
    steps = scope["steps"]
    if not isinstance(steps, list) or not steps:
        stop(EXIT_DENIED, "denied", "authorization_scope_steps_invalid")
    if any(key in scope for key in STEP_FIELDS):
        stop(EXIT_DENIED, "denied", "authorization_scope_mixed_format")
    for number, step in enumerate(steps, 1):
        if not isinstance(step, dict):
            stop(EXIT_DENIED, "denied", "authorization_scope_step_invalid", step=number, field="step")
        for key in STEP_FIELDS:
            value = step.get(key)

            if not isinstance(value, str) or not value.strip():
                stop(EXIT_DENIED, "denied", "authorization_scope_step_invalid", step=number, field=key)
        limit = step.get("max")
        if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
            stop(EXIT_DENIED, "denied", "authorization_scope_step_invalid", step=number, field="max")
    return steps


def write_identity(provider: str, action: str, account: str, resource_type: str, resource: str) -> dict[str, str]:
    return {
        "provider": normalize(provider).casefold(),
        "action": normalize(action).casefold(),
        "account": normalize(account),
        "resource_type": normalize(resource_type).casefold(),
        "resource": normalize(resource),
    }


def locate_step(args: argparse.Namespace, steps: list[dict[str, Any]]) -> int:
    """The 1-based step these exact CLI arguments name (--step picks one when two steps are identical)."""
    if args.step_write is not None and args.step_write < 1:
        stop(EXIT_DENIED, "denied", "step_write_invalid")

    wanted = write_identity(args.provider, args.action, args.account, args.resource_type, args.resource_target)
    if args.step is not None:
        if not 1 <= args.step <= len(steps):
            stop(EXIT_DENIED, "denied", "step_out_of_range", step=args.step, steps=len(steps))
        have = write_identity(*(steps[args.step - 1][key] for key in STEP_FIELDS))
        for key in STEP_FIELDS:
            if have[key] != wanted[key]:
                stop(EXIT_DENIED, "denied", f"authorization_scope_{key}_mismatch", step=args.step)
        return args.step
    matches = [number for number, step in enumerate(steps, 1) if write_identity(*(step[key] for key in STEP_FIELDS)) == wanted]
    if not matches:
        stop(EXIT_DENIED, "denied", "authorization_scope_step_mismatch")
    if len(matches) > 1:
        stop(EXIT_DENIED, "denied", "step_ambiguous", matching_steps=matches)
    return matches[0]


def resource_key_for(provider: str, account: str, resource_type: str, target: str) -> str:
    return digest({
        "schema": "controller-resource-key/v1",

        "provider": normalize(provider).casefold(),
        "account": normalize(account),
        "resource_type": normalize(resource_type).casefold(),
        "target": normalize(target),
    })


def step_resource_key(step: dict[str, Any]) -> str:
    return resource_key_for(step["provider"], step["account"], step["resource_type"], step["resource"])


def step_intent_id(args: argparse.Namespace, steps: list[dict[str, Any]], number: int, write: int, outcome_hash: str, scope_hash: str) -> str:
    """One deterministic intent per (fence, step, write); the node is recorded in the claim, not keyed."""
    step = steps[number - 1]
    return digest({
        "schema": "controller-write-intent/v2",
        "mission_id": args.mission_id,
        "next_play_id": args.next_play_id,
        "step": number,
        "step_write": write,
        "action": normalize(step["action"]).casefold(),
        "resource_key": step_resource_key(step),
        "outcome_hash": outcome_hash,
        "authorization_scope_hash": scope_hash,
