    checks = (
        ("STATUS", "ACTIVE", "mission_not_active"),

        ("CONTROLLER_THREAD_ID", str(claim.get("controller_thread_id", "")), "controller_thread_mismatch"),
        ("CONTROLLER_GENERATION", str(claim.get("controller_generation", "")), "controller_generation_mismatch"),
        ("CONTROLLER_HOST_ID", str(claim.get("controller_host_id", "")), "controller_host_mismatch"),
        ("NEXT_PLAY_ID", str(claim.get("next_play_id", "")), "next_play_mismatch"),
        ("NEXT_PLAY_OUTCOME_HASH", str(claim.get("outcome_hash", "")), "next_play_outcome_mismatch"),
        ("AUTHORIZATION_REF", str(claim.get("authorization_ref", "")), "authorization_ref_mismatch"),
        ("AUTHORIZATION_SCOPE_HASH", str(claim.get("authorization_scope_hash", "")), "authorization_scope_mismatch"),
    )
    for field, expected, reason in checks:
        if fields.get(field) != expected:
            stop(EXIT_DENIED, "denied", reason)
    validate_node(fields, str(claim.get("node_id", "")))


