"""Descriptor-relative bookkeeping I/O; never follows a symlink component."""
import os
import stat
import uuid
import fcntl
from pathlib import Path
from contextlib import contextmanager

_BOUND_ROOT = None
_BOUND_FD = None


def absolute(path):
    p = Path(path).expanduser().absolute()
    if '..' in p.parts:
        raise ValueError('parent traversal refused')
    return p


@contextmanager
def directory(path, create=False):
    p = absolute(path)
    if _BOUND_ROOT is not None and (p == _BOUND_ROOT or _BOUND_ROOT in p.parents):
        fd=os.dup(_BOUND_FD)
        parts=p.relative_to(_BOUND_ROOT).parts
    else:
        fd=os.open('/',os.O_RDONLY|os.O_DIRECTORY)
        parts=p.parts[1:]
    try:
        for part in parts:
            if create:
                try: os.mkdir(part, 0o700, dir_fd=fd)
                except FileExistsError: pass
            nxt = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=fd)
            os.close(fd)
            fd = nxt
        if os.fstat(fd).st_uid != os.getuid():
            raise ValueError('directory owner mismatch')

        yield fd
    finally:
        os.close(fd)


def checked(fd):
    s = os.fstat(fd)
    if not stat.S_ISREG(s.st_mode) or s.st_nlink != 1 or s.st_uid != os.getuid():
        raise ValueError('untrusted file at operation')
    return fd


@contextmanager
def file(path, flags=os.O_RDONLY, mode=0o600):
    p = absolute(path)
    with directory(p.parent) as parent:
        fd = os.open(p.name, flags | os.O_NOFOLLOW | os.O_NONBLOCK, mode, dir_fd=parent)
        try:
            checked(fd)
            yield fd
        finally: os.close(fd)


def read_bytes(path):
    with file(path) as fd:
        chunks=[]
        while True:
            b=os.read(fd, 65536)
            if not b: return b''.join(chunks)
            chunks.append(b)


def read_text(path): return read_bytes(path).decode('utf-8')


def write_all(fd, data):
    view=memoryview(data)
    while view:
        n=os.write(fd,view)
        if not n: raise OSError('short write')
        view=view[n:]


def atomic_write(path, data, exclusive=False):
    if isinstance(data,str): data=data.encode('utf-8')
    p=absolute(path)

    with directory(p.parent) as parent:
        # Reject existing poison even though replace itself does not follow it.
        try:
            fd=os.open(p.name,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=parent)
        except FileNotFoundError: pass
        else:
            try: checked(fd)
            finally: os.close(fd)
        tmp='.'+p.name+'.'+uuid.uuid4().hex
        fd=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600,dir_fd=parent)
        try:
            write_all(fd,data); os.fsync(fd)
        finally: os.close(fd)
        try:
            if exclusive:
                os.link(tmp,p.name,src_dir_fd=parent,dst_dir_fd=parent,follow_symlinks=False)
            else: os.replace(tmp,p.name,src_dir_fd=parent,dst_dir_fd=parent)
            os.fsync(parent)
        finally:
            try: os.unlink(tmp,dir_fd=parent)
            except FileNotFoundError: pass


def copy(source,target): atomic_write(target,read_bytes(source))


def append(path,text):
    with file(path,os.O_RDWR|os.O_APPEND) as fd:
        fcntl.flock(fd,fcntl.LOCK_EX)

        size=os.fstat(fd).st_size
        tail=os.pread(fd,1,size-1) if size else b'\n'
        write_all(fd,('' if tail==b'\n' else '\n').encode()+text.encode()+b'\n')
        os.fsync(fd)


def exists(path):
    p=absolute(path)
    try:
        with directory(p.parent) as parent: os.stat(p.name,dir_fd=parent,follow_symlinks=False)
        return True
    except FileNotFoundError: return False


def mkdir(path,parents=False,exist_ok=False):
    p=absolute(path)
    with directory(p.parent,create=parents) as parent:
        try: os.mkdir(p.name,0o700,dir_fd=parent)
        except FileExistsError:
            if not exist_ok: raise
    with directory(p): pass


def unlink(path,dir_only=False):
    p=absolute(path)
    with directory(p.parent) as parent:
        if dir_only: os.rmdir(p.name,dir_fd=parent)
        else: os.unlink(p.name,dir_fd=parent)
        os.fsync(parent)


def move(source,target):
    # Used under a transaction lock. Copy+unlink keeps interruption fail-closed.
    copy(source,target)
    unlink(source)


def listdir(path):

    with directory(path) as fd: return [absolute(path)/n for n in os.listdir(fd)]


def lock_fd(path):
    p=absolute(path)
    with directory(p.parent) as parent:
        fd=os.open(p.name,os.O_RDWR|os.O_CREAT|os.O_NOFOLLOW|os.O_NONBLOCK,0o600,dir_fd=parent)
        try: checked(fd); fcntl.flock(fd,fcntl.LOCK_EX)
        except BaseException: os.close(fd); raise
        return fd


@contextmanager
def locked(path):
    fd=lock_fd(path)
    try: yield
    finally: os.close(fd)


def bind_root(path):
    """Pin one validated helper home for this process, retaining its directory inode."""
    global _BOUND_ROOT,_BOUND_FD
    p=absolute(path)
    if _BOUND_ROOT is not None:
        if p!=_BOUND_ROOT: raise ValueError('process already bound to another home')
        return
    with directory(p) as fd: pinned=os.dup(fd)
    _BOUND_ROOT=p
    _BOUND_FD=pinned


def directory_exists(path):
    try:
        with directory(path): pass
        return True
    except FileNotFoundError: return False

"""Team-owned bookkeeping paths. A routing boundary, not an OS sandbox."""
import json
import os
from pathlib import Path
import re
import stat
import hashlib
import unicodedata
import safe_io as io


class ScopeError(ValueError):
    pass


def clean_path(value):
    p = Path(value).expanduser().absolute()
    if p != p.resolve():
        raise ScopeError(f"noncanonical or linked path: {p}")
    for part in (p, *p.parents):
        if part.is_symlink():
            raise ScopeError(f"linked path: {part}")
    return p


def private_file(path):
    p = clean_path(path)
    if io.exists(p):
        with io.file(p): pass
    return p


def bound_home(script_path):
    script = clean_path(script_path)
    if script.parent.name != 'scripts':
        raise ScopeError('helper must live in the team scripts directory')
    if script.parent.parent.name == 'alex-director' and script.parents[2].name == 'roles':
        home = script.parents[3]
    else:
        home = script.parents[1]
    if not home.is_dir() or home.stat().st_uid != os.getuid():

    raise ScopeError('team home is unavailable or belongs to another user')
if (home / '.setup-in-progress').exists():
    raise ScopeError('team setup is incomplete; inspect the partial output before use')
io.bind_root(home)
bp = private_file(home / 'TEAM_BINDING.json')
try:
    binding = strict_json(io.read_text(bp))
except (OSError, ValueError) as exc:
    raise ScopeError(f'team binding unavailable: {exc}') from exc
if binding.get('schema') != 'independent-team-binding/v1':
    raise ScopeError('unknown team binding schema')
if binding.get('team_home') != str(home):
    raise ScopeError('binding belongs to a different home; explicit relocation is required')
if not re.fullmatch(r'team-[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}', binding.get('team_id', '')):
    raise ScopeError('missing or invalid fresh team identity')
ident = binding.get('director_identity') or {}
if any(not isinstance(ident.get(k), str) or not ident[k].strip() for k in ('platform', 'thread_id', 'host_id')):

        raise ScopeError('first-chat Director identity is missing')
    context = runtime_context(home, binding)
    if context.get("team_id") != binding["team_id"] or context.get("role") not in ("director", "controller") or not context.get("thread_id"):
        raise ScopeError("trusted runtime principal is unavailable")
    return home, binding


def ledger_path(home, supplied):
    p = private_file(supplied)
    if p != clean_path(home) / 'DIRECTOR_STATE.md':
        raise ScopeError('ledger belongs outside this team')
    for suffix in ('.bak', '.lock'):
        private_file(str(p) + suffix)
    return p


def graph_path(home, supplied):
    p = private_file(supplied)
    if p.parent != clean_path(home) / 'mission-graphs' or p.suffix != '.md':
        raise ScopeError('graph belongs outside this team')
    private_file(str(p) + '.bak')
    return p


def log_path(home, supplied=None, name='run-log.md'):
    expected = clean_path(home) / 'system' / name
    p = private_file(supplied if supplied is not None else expected)
    if p != expected:

        raise ScopeError('bookkeeping log belongs outside this team')
    return p


def claims_path(home):
    p = clean_path(Path(home) / '.runtime' / 'controller-write-claims')
    for d in (p.parent,p):
        if io.exists(d):
            with io.directory(d): pass
    return p


def authorization_path(home, supplied):
    p = private_file(supplied)
    if p.parent != clean_path(home) / 'mission-graphs' or p.suffix != '.json':
        raise ScopeError('authorization record belongs outside this team')
    return p


def check_mission_identity(binding, fields):
    if fields.get('TEAM_ID') != binding['team_id']:
        raise ScopeError('mission belongs to another team or has no TEAM_ID')
    if fields.get('SUPERVISING_DIRECTOR_THREAD_ID') != binding['director_identity']['thread_id']:
        raise ScopeError('mission return address is not this team Director')


def check_text_identity(binding, text):
    fields = {}
    for key in ('TEAM_ID', 'SUPERVISING_DIRECTOR_THREAD_ID'):
        hits = re.findall(r'^' + key + r':\s*([^\n]+)$', text, re.M)
        if len(hits) != 1:

            raise ScopeError(f'exactly one {key} field required')
        fields[key] = hits[0].strip()
    check_mission_identity(binding, fields)


def runtime_context(home, binding):
    raise ScopeError('trusted launcher required; native activation unsupported')


def require_role(home, binding, role):
    c = runtime_context(home, binding)
    if c.get('role') != role or c.get('team_id') != binding['team_id']:
        raise ScopeError('runtime role mismatch')
    if role == 'director' and c.get('thread_id') != binding['director_identity']['thread_id']:
        raise ScopeError('Director principal mismatch')
    return c


def strict_json(raw):
    def pairs(items):
        out = {}
        for k,v in items:
            if k in out: raise ScopeError('duplicate JSON key')
            out[k] = v
        return out
    def constant(value): raise ScopeError('nonfinite JSON value')
    return json.loads(raw, object_pairs_hook=pairs, parse_constant=constant)


def canonical_hash(value):
    def norm(v):
        if isinstance(v,str): return unicodedata.normalize('NFC',v)

        if isinstance(v,list): return [norm(x) for x in v]
        if isinstance(v,dict): return {unicodedata.normalize('NFC',k):norm(x) for k,x in v.items()}
        return v
    return hashlib.sha256(json.dumps(norm(value),sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()


def text_fields(text):
    fields = {}
    for k,v in re.findall(r'^([A-Z][A-Z0-9_]*):[ \t]*(.*?)[ \t]*$',text,re.M):
        if k in fields: raise ScopeError('duplicate mission field: '+k)
        fields[k] = v
    return fields


