    raise ScopeError('authorization mission/play/owner identity mismatch')
generation=record['controller_generation']
if isinstance(generation,bool) or not isinstance(generation,int) or generation<1 or str(generation)!=fields.get('CONTROLLER_GENERATION'):
    raise ScopeError('authorization generation mismatch')

    if not isinstance(record['authorization_scope'],dict) or not record['authorization_scope']:
        raise ScopeError('authorization scope missing')
