        raise ScopeError('requested scope differs from approved scope')
    if c.get('role')=='controller' and c.get('thread_id') != record['controller_thread_id']:
        raise ScopeError('controller principal mismatch')
    if c.get('role')=='director' and c.get('thread_id') != record['director_thread_id']:
        raise ScopeError('Director principal mismatch')
    return record


def validate_references(home,binding,body):
    fields=text_fields(body)
    check_mission_identity(binding,fields)
    mid=fields.get('MISSION_ID')
    if not mid: raise ScopeError('missing mission identity')
    graph=graph_path(home,fields.get('MISSION_GRAPH',''))
    graph_text=io.read_text(graph)

    check_text_identity(binding,graph_text)
    if single_field(graph_text,'MISSION_ID')!=mid:
        raise ScopeError('graph mission identity mismatch')
    ref=fields.get('AUTHORIZATION_REF')
    if ref and ref!='NONE': validate_authorization(home,binding,fields)
    elif fields.get('STATUS')=='ACTIVE' and fields.get('AUTHORIZATION_SCOPE_HASH') not in (None,'','NONE'):
        raise ScopeError('protected active mission requires authorization')
    return fields


def single_field(text,key):
    hits=re.findall(r'^'+re.escape(key)+r':[ \t]*([^\n]*)$',text,re.M)
    if len(hits)!=1: raise ScopeError('exactly one '+key+' field required')
    return hits[0].strip()

