def run_pending(self,limit=8):
 """Explicit foreground pump; no daemon, schedule or hidden ongoing service."""
 if self.state.get('pending_delivery') is not None:raise ValueError('unconfirmed delivery requires explicit reconciliation')
 self._advance_rollover()
