 while self.state['queue'] and count<limit:
  item=self.state['queue'][0]
  if item.get('target') in self.state.get('retired_directors',[]) or item.get('sender') in self.state.get('retired_directors',[]):raise ValueError('queued retired-actor message requires explicit reconciliation')
  # Persist consumption first: crash is lost/unconfirmed delivery, never auto replay.
  self.state['queue']=self.state['queue'][1:];self.state['pending_delivery']=item;self._save()
  if item['kind']=='dispatch':
   self.registry.context(item['sender']);self._dispatch(item['mission_id'])
  else:
   op='resume' if item['kind']=='resume' else 'send'

   self.registry.recipient_check(item['sender'],item['target'],op)
   if op=='resume':self.client.resume(item['target'])
   else:
    self._ensure_loaded(item['target']);self.client.turn(item['target'],item['text'])
   self.events.append({'kind':'native_delivery','sender':item['sender'],'recipient':item['target'],'operation':op,'status':'delivered'})
  self.state.pop('pending_delivery',None);self._save();count+=1
  self._advance_rollover()
