def _advance_rollover(self):
 """One bounded foreground checkpoint; delivery uses client.turn, never recursion."""
 j=self.state.get('rollover')
 if not j or not j.get('automatic') or j['stage']=='complete':return None
 try:
  if j['stage']=='requested':
   candidate=self.rollover_checkpoint()
   if candidate is None:
    result={'status':'pending_safe_checkpoint','source':j['source']}
    self.events.append({'kind':'foreground_rollover',**result});return result
  if j['stage']!='candidate':raise ValueError('automatic successor intent requires explicit reconciliation; no replay')

  successor=self.deliver_rollover()
  result={'status':'transferred','source':j['source'],'successor':successor}
  self.events.append({'kind':'foreground_rollover',**result});return result
 except Exception as exc:
  j['last_foreground_error']=str(exc);self._save()
  self.events.append({'kind':'foreground_rollover','status':'reconciliation_required','stage':j['stage'],'reason':str(exc)})
  raise

