  # Historical total is never a current-context estimate. Missing metrics stay unknown.
  if type(used) is int and used>=0 and type(window) is int and window>0 and used/window>=self.context_ratio:
   self.request_rollover(reason='observed last native input/context ratio',observation={'input_tokens':used,'context_window':window,'ratio':self.context_ratio},automatic=True)

